// Decides which past client gets a retention message right now. Pure logic: reads the sheets, writes nothing.
// Decide a qué clienta (ya atendida) le toca un mensaje de retención ahora. Solo lee las hojas, no escribe nada.
//   Based on her LAST visit (Citas.estado = asistio) / Según su ÚLTIMA visita:
//   retoque      → visit end + Servicios.retoque_dias       → "time for your touch-up, shall I book it?" → 1 reminder if silent
//   reactivacion → no visit for Negocio.dias_reactivacion    → "we miss you" + Negocio.oferta_reactivacion → 1 reminder if silent
//                  (for long touch-ups, e.g. fillers 270 d, it waits until retoque_dias + 30)
//   WhatsApp failed (send error or Twilio status callback) → the invitation once by email, if she has one
//   WhatsApp fallido → la invitación una vez por email, si tiene
// Never: opt_out, open case (incl. low rating), upcoming appointment, another touch in the last 14 days.
// Nunca: opt_out, caso abierto (incluye nota baja), cita futura, otro toque en los últimos 14 días.
// Sent messages live in Seguimientos (origen = P35, secuencia, ronda = start of her last visit, paso = invitacion | recordatorio).

// ⚙️ CONFIG — DEMO_MODE: minutes instead of days (live demo). false = production times.
// ⚙️ CONFIG — DEMO_MODE: minutos en vez de días (demo en vivo). false = tiempos de producción.
const DEMO_MODE = true;
const DAY = DEMO_MODE ? 1 : 24 * 60;                  // minutes in a "day" / minutos en un "día"
const DEMO_RETOQUE_MIN = 3;                           // DEMO: touch-up invite 3 min after the visit ends
const DEMO_REACTIVACION_MIN = 15;                     // DEMO: reactivation 15 min after the visit ends
const REMINDER_MIN = DEMO_MODE ? 5 : 7 * DAY;         // reminder after the invite if she stays silent
const GAP_MIN = DEMO_MODE ? 2 : 14 * DAY;             // min. gap since ANY other touch (P32-P35) / descanso mínimo
const REACTIVACION_EXTRA_DIAS = 30;                   // long touch-ups: reactivation = retoque_dias + 30
const SEND_HOURS = [10, 19];                          // production only, Mon-Sat (marketing) / solo producción, lun-sáb
const MAX_PER_RUN = 20;
const ACTIVE = ['agendada', 'confirmada', 'reprogramada'];
const FAILED = ['failed', 'undelivered', 'error'];

// --- Sheets → rows (same order as the batchGet URL) / Hojas → filas (mismo orden que la URL)
const SHEETS = ['Leads', 'Citas', 'Seguimientos', 'Calificaciones', 'Conversaciones', 'Escalamientos', 'Negocio', 'Servicios'];
const ranges = $input.first().json.valueRanges || [];
const toRows = (vr) => {
  const v = (vr && vr.values) || [];
  const h = v[0] || [];
  return v.slice(1)
    .map((r, i) => { const o = { row_number: i + 2 }; h.forEach((k, j) => { o[k] = r[j] === undefined ? '' : String(r[j]); }); return o; })
    .filter(o => h.some(k => o[k] !== ''));
};
const t = {};
SHEETS.forEach((s, i) => { t[s] = toRows(ranges[i]); });
const negocio = {};
t.Negocio.forEach(r => { if (r.clave) negocio[r.clave] = r.valor; });

const tz = negocio.zona_horaria || 'America/Phoenix';
const now = $now.setZone(tz);
const parse = s => {
  const str = String(s || '').trim();
  for (const f of ['yyyy-MM-dd HH:mm:ss', 'yyyy-MM-dd HH:mm']) {
    const d = DateTime.fromFormat(str, f, { zone: tz });
    if (d.isValid) return d;
  }
  return null;
};
const fmt = d => (d ? d.toFormat('yyyy-MM-dd HH:mm:ss') : '');
const servicios = {};
t.Servicios.forEach(r => { if (r.nombre_es) servicios[r.nombre_es] = r; });
const diasReactivacion = parseInt(negocio.dias_reactivacion, 10) || 120;

const inHours = DEMO_MODE || (now.weekday !== 7 && now.hour >= SEND_HOURS[0] && now.hour < SEND_HOURS[1]);

const due = [];
const report = [];   // why each client was / was not picked / por qué se eligió o no cada clienta
for (const lead of t.Leads) {
  const why = (motivo, extra = {}) => report.push({ lead_id: lead.lead_id, motivo, ...extra });
  const citas = t.Citas.filter(c => c.lead_id === lead.lead_id);
  const visitas = citas.filter(c => c.estado === 'asistio' && parse(c.inicio))
    .sort((a, b) => parse(b.inicio) - parse(a.inicio));
  if (!visitas.length) { why('nunca_asistio'); continue; }
  const visita = visitas[0];   // her last visit = the round / su última visita = la ronda
  const fin = parse(visita.fin) || parse(visita.inicio);

  if (lead.estado === 'opt_out') { why('opt_out'); continue; }
  const whatsapp = lead.whatsapp || visita.whatsapp;
  if (!whatsapp) { why('sin_whatsapp'); continue; }
  // An open case means a person is handling her (low ratings open one too). / Caso abierto = la atiende una persona.
  if (t.Escalamientos.some(e => e.lead_id === lead.lead_id && e.estado === 'abierto')) { why('escalamiento_abierto'); continue; }
  // Already coming back → nothing to do. / Ya tiene cita → nada que hacer.
  if (citas.some(c => ACTIVE.includes(c.estado) && (parse(c.inicio) || now) > now)) { why('tiene_cita'); continue; }

  // Which sequence is due / Qué secuencia toca
  const srv = servicios[visita.servicio] || {};
  const retoqueDias = parseInt(srv.retoque_dias, 10) || 0;
  const retoqueAt = retoqueDias ? fin.plus({ minutes: DEMO_MODE ? DEMO_RETOQUE_MIN : retoqueDias * DAY }) : null;
  const reactDias = Math.max(diasReactivacion, retoqueDias ? retoqueDias + REACTIVACION_EXTRA_DIAS : 0);
  const reactAt = fin.plus({ minutes: DEMO_MODE ? DEMO_REACTIVACION_MIN : reactDias * DAY });
  let secuencia;
  if (now >= reactAt) secuencia = 'reactivacion';
  else if (retoqueAt && now >= retoqueAt) secuencia = 'retoque';
  else { why('aun_no', { cuando: fmt(retoqueAt || reactAt), proxima: retoqueAt ? 'retoque' : 'reactivacion' }); continue; }

  // Steps already sent in this round / Pasos ya enviados en esta ronda
  const sent = t.Seguimientos.filter(s => s.origen === 'P35' && s.lead_id === lead.lead_id && s.secuencia === secuencia && s.ronda === visita.inicio);
  const sentWa = p => sent.find(s => s.paso === p && s.canal !== 'email');
  const sentEmail = p => sent.find(s => s.paso === p && s.canal === 'email');
  const failed = s => {
    const conv = s.message_id ? t.Conversaciones.find(m => m.wa_message_sid === s.message_id) : null;
    const estado = String((conv && conv.estado_entrega) || s.resultado || '').toLowerCase();
    return FAILED.some(f => estado.startsWith(f));
  };
  const hasEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(lead.email || '').trim());

  let paso = null;
  let canal = 'whatsapp';
  const inv = sentWa('invitacion');
  if (!inv) paso = 'invitacion';
  else if (failed(inv)) {
    if (sentEmail('invitacion')) { why('invitacion_por_email', { secuencia }); continue; }   // no reminder by email
    if (!hasEmail) { why('whatsapp_fallido', { secuencia }); continue; }
    paso = 'invitacion'; canal = 'email';
  } else {
    if (sentWa('recordatorio')) { why('secuencia_terminada', { secuencia }); continue; }
    const invAt = parse(inv.fecha);
    if (!invAt) { why('fecha_invitacion_invalida'); continue; }
    // She wrote after the invite → Sofía is talking with her (yes, no or questions). / Escribió → la atiende Sofía.
    const replied = t.Conversaciones.some(m => m.lead_id === lead.lead_id && m.rol === 'user' && (parse(m.fecha) || invAt) > invAt);
    if (replied) { why('respondio', { secuencia }); continue; }
    const remindAt = invAt.plus({ minutes: REMINDER_MIN });
    if (now < remindAt) { why('aun_no', { secuencia, paso: 'recordatorio', cuando: fmt(remindAt) }); continue; }
    paso = 'recordatorio';
  }

  // Rest between touches from any flow (her own reminder is exempt) / Descanso entre toques de cualquier flujo
  const lastTouch = t.Seguimientos
    .filter(s => s.lead_id === lead.lead_id && !(s.origen === 'P35' && s.secuencia === secuencia && s.ronda === visita.inicio))
    .map(s => parse(s.fecha)).filter(Boolean).sort((a, b) => b - a)[0];
  if (lastTouch && now < lastTouch.plus({ minutes: GAP_MIN })) { why('toque_reciente', { secuencia, paso, cuando: fmt(lastTouch.plus({ minutes: GAP_MIN })) }); continue; }
  if (!inHours) { why('fuera_de_horario', { secuencia, paso }); continue; }

  // Offer only in reactivation, and never if her last visit was rated 1-3. / Oferta solo en reactivación y nunca con nota baja.
  const nota = t.Calificaciones.filter(c => c.cita_id === visita.cita_id).map(c => parseInt(c.nota, 10)).pop();
  const oferta = secuencia === 'reactivacion' && !(nota <= 3) ? (negocio.oferta_reactivacion || '') : '';

  due.push({
    lead_id: lead.lead_id, cita_id: visita.cita_id, nombre: lead.nombre || visita.nombre, whatsapp,
    idioma: lead.idioma || 'es', email: lead.email || '', servicio: visita.servicio,
    servicio_en: srv.nombre_en || visita.servicio, ultima_visita: visita.inicio,
    secuencia, paso, canal, ronda: visita.inicio, oferta, nota_ultima_visita: nota || '',
    // Days for the message text (DEMO uses the configured days so the text reads real) / Días para el texto del mensaje
    dias_desde_visita: DEMO_MODE ? (secuencia === 'retoque' ? retoqueDias : reactDias) : Math.floor(now.diff(fin, 'days').days)
  });
  why('toca', { secuencia, paso, canal });
}

const picked = due.slice(0, MAX_PER_RUN);
return picked.length
  ? picked.map(d => ({ json: { ...d, demo_mode: DEMO_MODE, ahora: fmt(now), negocio } }))
  : [{ json: { nada: true, ahora: fmt(now), demo_mode: DEMO_MODE, report } }];

// Fills the fixed retention template (Meta marketing template style: fixed text + variables). No AI: $0 per message.
// Llena la plantilla fija de retención (estilo plantilla de marketing de Meta: texto fijo + variables). Sin IA: $0 por mensaje.
// Templates / Plantillas: retoque (touch-up due) · reactivacion (we miss you + offer) × invitacion | recordatorio
// The offer text comes from Negocio (oferta_reactivacion / _en); the picker leaves it empty if she rated her last visit 1-3.
// La oferta sale de Negocio (oferta_reactivacion / _en); el picker la deja vacía si calificó su última visita 1-3.
// WhatsApp → input for P31e - Lumière Send WhatsApp. Email (fallback, invitation only) → input for P32c - Lumière Send Email.
// "Consulta + …" → "consulta + …" mid-sentence; brand names with inner capitals ("HydraFacial") stay as they are
const lower = s => { const w = String(s || '').split(/\s/)[0]; return w.length > 1 && w.slice(1) === w.slice(1).toLowerCase() ? s[0].toLowerCase() + s.slice(1) : s; };
const STOP = { es: '\n\nResponde STOP si no quieres recibir más mensajes.', en: '\n\nReply STOP to opt out.' };
// "3 meses" / "6 semanas" since her visit / desde su visita
const tiempo = (dias, lang) => dias >= 56
  ? (lang === 'es' ? `${Math.round(dias / 30)} meses` : `${Math.round(dias / 30)} months`)
  : (lang === 'es' ? `${Math.max(1, Math.round(dias / 7))} semanas` : `${Math.max(1, Math.round(dias / 7))} weeks`);
const WA = {
  es: {
    retoque: {
      invitacion: v => `Hola ${v.nombre} 💛 Ya van ${v.tiempo} desde tu ${lower(v.servicio)} en ${v.spa}, y este es el mejor momento para tu retoque: así mantienes tus resultados. ¿Quieres que te busque un horario? Respóndeme por aquí y lo agendamos en un momento.${STOP.es}`,
      recordatorio: v => `Hola ${v.nombre}, te escribo de nuevo por si se te pasó 😊 ¿Te ayudo a agendar tu retoque de ${lower(v.servicio)}? Respóndeme y te busco un horario.`
    },
    reactivacion: {
      invitacion: v => `Hola ${v.nombre} 💛 Hace un tiempo que no te vemos en ${v.spa} y te extrañamos.${v.oferta ? ` Para darte la bienvenida de vuelta: *${v.oferta}*.` : ''} ¿Quieres que te busque un horario? Respóndeme por aquí y lo agendamos en un momento.${STOP.es}`,
      recordatorio: v => v.oferta
        ? `Hola ${v.nombre}, solo para recordarte que tu beneficio sigue disponible: *${v.oferta}* 😊 Si quieres, respóndeme y te agendo en un momento.`
        : `Hola ${v.nombre}, aquí seguimos cuando quieras volver 😊 Si quieres, respóndeme y te agendo en un momento.`
    }
  },
  en: {
    retoque: {
      invitacion: v => `Hi ${v.nombre} 💛 It's been ${v.tiempo} since your ${lower(v.servicio)} at ${v.spa}, and now is the best time for your touch-up to keep your results. Would you like me to find you a time? Just reply here and we'll book it in a moment.${STOP.en}`,
      recordatorio: v => `Hi ${v.nombre}, just following up in case you missed it 😊 Can I help you book your ${lower(v.servicio)} touch-up? Reply and I'll find you a time.`
    },
    reactivacion: {
      invitacion: v => `Hi ${v.nombre} 💛 It's been a while since we last saw you at ${v.spa}, and we miss you.${v.oferta ? ` To welcome you back: *${v.oferta}*.` : ''} Would you like me to find you a time? Just reply here and we'll book it in a moment.${STOP.en}`,
      recordatorio: v => v.oferta
        ? `Hi ${v.nombre}, just a reminder that your welcome-back offer is still available: *${v.oferta}* 😊 Reply and I'll book you in a moment.`
        : `Hi ${v.nombre}, we're here whenever you'd like to come back 😊 Reply and I'll book you in a moment.`
    }
  }
};
// Email fallback (paragraphs split by a blank line; P32c adds logo, WhatsApp button, signature and unsubscribe footer)
// Respaldo por email (párrafos separados por línea en blanco; P32c pone logo, botón a WhatsApp, firma y pie de baja)
const EMAIL = {
  es: {
    retoque: v => ({ asunto: `${v.nombre}, ya te toca tu retoque`, cta: 'Agendar por WhatsApp',
      mensaje: `Hola ${v.nombre},\n\nYa van ${v.tiempo} desde tu ${lower(v.servicio)} en ${v.spa}, y este es el mejor momento para tu retoque: así mantienes tus resultados.\n\nEscríbenos por WhatsApp y te buscamos un horario en un momento.` }),
    reactivacion: v => ({ asunto: `Te extrañamos en ${v.spa}`, cta: 'Agendar por WhatsApp',
      mensaje: `Hola ${v.nombre},\n\nHace un tiempo que no te vemos y te extrañamos.${v.oferta ? `\n\nPara darte la bienvenida de vuelta: ${v.oferta}.` : ''}\n\nEscríbenos por WhatsApp y te buscamos un horario en un momento.` })
  },
  en: {
    retoque: v => ({ asunto: `${v.nombre}, your touch-up is due`, cta: 'Book on WhatsApp',
      mensaje: `Hi ${v.nombre},\n\nIt's been ${v.tiempo} since your ${lower(v.servicio)} at ${v.spa}, and now is the best time for your touch-up to keep your results.\n\nMessage us on WhatsApp and we'll find you a time in a moment.` }),
    reactivacion: v => ({ asunto: `We miss you at ${v.spa}`, cta: 'Book on WhatsApp',
      mensaje: `Hi ${v.nombre},\n\nIt's been a while since we last saw you, and we miss you.${v.oferta ? `\n\nTo welcome you back: ${v.oferta}.` : ''}\n\nMessage us on WhatsApp and we'll find you a time in a moment.` })
  }
};

return $input.all().map(item => {
  const r = item.json;
  const n = r.negocio || {};
  const lang = String(r.idioma).toLowerCase().startsWith('en') ? 'en' : 'es';
  const v = {
    nombre: String(r.nombre || '').trim().split(/\s+/)[0] || (lang === 'es' ? 'hola' : 'there'),
    spa: n.nombre || 'Lumière Aesthetics',
    servicio: lang === 'en' ? (r.servicio_en || r.servicio) : r.servicio,
    tiempo: tiempo(Number(r.dias_desde_visita) || 0, lang),
    oferta: r.oferta ? (lang === 'en' ? (n.oferta_reactivacion_en || r.oferta) : r.oferta) : ''
  };
  const base = { lead_id: r.lead_id, cita_id: r.cita_id, paso: r.paso, secuencia: r.secuencia, ronda: r.ronda,
                 canal: r.canal, idioma: lang, origen: 'P35' };
  if (r.canal === 'email') {
    const e = EMAIL[lang][r.secuencia](v);
    return { json: { ...base, email: r.email, asunto: e.asunto, mensaje: e.mensaje, cta_texto: e.cta } };
  }
  return { json: { ...base, whatsapp: r.whatsapp, mensaje: WA[lang][r.secuencia][r.paso](v), rol: 'assistant', off_topic: false, solo_registrar: false } };
});

// One row for Seguimientos per message, sent or failed (WhatsApp branch = output 0, email branch = output 1).
// Una fila en Seguimientos por mensaje, enviado o fallido (rama WhatsApp = salida 0, rama email = salida 1).
// Columns / Columnas: seguimiento_id, fecha, lead_id, origen, secuencia, ronda, paso, canal, mensaje, message_id, resultado, cita_id
const BRANCH = 0;   // 0 = WhatsApp (after P31e) · 1 = email (after P32c)
const msgs = $('Is WhatsApp?').all(BRANCH);
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
return $input.all().map((item, i) => {
  const t = msgs[i].json;
  const r = item.json || {};
  const fecha = r.fecha || $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
  const resultado = BRANCH === 0
    ? ((r.ok === false || r.estado_entrega === 'error') ? 'error: ' + (r.error || 'send_failed') : (r.estado_entrega || 'queued'))
    : (r.ok ? 'sent' : 'error: ' + (r.error || 'send_failed'));
  const mensaje = BRANCH === 0 ? t.mensaje : `${t.asunto}\n\n${t.mensaje}`;
  return { json: {
    row: ['SEG-' + fecha.slice(0, 10).replace(/-/g, '') + '-' + rand(), fecha, t.lead_id, 'P35', t.secuencia, t.ronda, t.paso,
          t.canal, mensaje, r.wa_message_sid || r.message_id || '', resultado, t.cita_id],
    cita_id: t.cita_id, paso: t.paso, canal: t.canal, resultado
  } };
});

// One row for Seguimientos per message, sent or failed (WhatsApp branch = output 0, email branch = output 1).
// Una fila en Seguimientos por mensaje, enviado o fallido (rama WhatsApp = salida 0, rama email = salida 1).
// Columns / Columnas: seguimiento_id, fecha, lead_id, origen, secuencia, ronda, paso, canal, mensaje, message_id, resultado, cita_id
const BRANCH = 1;   // 0 = WhatsApp (after P31e) · 1 = email (after P32c)
const msgs = $('Is WhatsApp?').all(BRANCH);
const rand = () => Math.random().toString(36).slice(2, 7).toUpperCase();
return $input.all().map((item, i) => {
  const t = msgs[i].json;
  const r = item.json || {};
  const fecha = r.fecha || $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss');
  const resultado = BRANCH === 0
    ? ((r.ok === false || r.estado_entrega === 'error') ? 'error: ' + (r.error || 'send_failed') : (r.estado_entrega || 'queued'))
    : (r.ok ? 'sent' : 'error: ' + (r.error || 'send_failed'));
  const mensaje = BRANCH === 0 ? t.mensaje : `${t.asunto}\n\n${t.mensaje}`;
  return { json: {
    row: ['SEG-' + fecha.slice(0, 10).replace(/-/g, '') + '-' + rand(), fecha, t.lead_id, 'P35', t.secuencia, t.ronda, t.paso,
          t.canal, mensaje, r.wa_message_sid || r.message_id || '', resultado, t.cita_id],
    cita_id: t.cita_id, paso: t.paso, canal: t.canal, resultado
  } };
});
